3418: 		public override void EmitBranchable (EmitContext ec, Label target, bool on_true)
3419: 		{
3420: 			ILGenerator ig = ec.ig;
3421: 
3422: 			//
3423: 			// This is more complicated than it looks, but its just to avoid
3424: 			// duplicated tests: basically, we allow ==, !=, >, <, >= and <=
3425: 			// but on top of that we want for == and != to use a special path
3426: 			// if we are comparing against null
3427: 			//
3428: 			if ((oper == Operator.Equality || oper == Operator.Inequality) && (left is Constant || right is Constant)) {
3429: 				bool my_on_true = oper == Operator.Inequality ? on_true : !on_true;
3430: 				
3431: 				//
3432: 				// put the constant on the rhs, for simplicity
3433: 				//
3434: 				if (left is Constant) {
3435: 					Expression swap = right;
3436: 					right = left;
3437: 					left = swap;
3438: 				}
3439: 				
3440: 				if (((Constant) right).IsZeroInteger) {
3441: 					left.EmitBranchable (ec, target, my_on_true);
3442: 					return;
3443: 				}
3444: 				if (right.Type == TypeManager.bool_type) {
3445: 					// right is a boolean, and it's not 'false' => it is 'true'
3446: 					left.EmitBranchable (ec, target, !my_on_true);
3447: 					return;
3448: 				}
3449: 
3450: 			} else if (oper == Operator.LogicalAnd) {
3451: 
3452: 				if (on_true) {
3453: 					Label tests_end = ig.DefineLabel ();
3454: 					
3455: 					left.EmitBranchable (ec, tests_end, false);
3456: 					right.EmitBranchable (ec, target, true);
3457: 					ig.MarkLabel (tests_end);					
3458: 				} else {
3459: 					//
3460: 					// This optimizes code like this 
3461: 					// if (true && i > 4)
3462: 					//
3463: 					if (!(left is Constant))
3464: 						left.EmitBranchable (ec, target, false);
3465: 
3466: 					if (!(right is Constant)) 
3467: 						right.EmitBranchable (ec, target, false);
3468: 				}
3469: 				
3470: 				return;
3471: 				
3472: 			} else if (oper == Operator.LogicalOr){
3473: 				if (on_true) {
3474: 					left.EmitBranchable (ec, target, true);
3475: 					right.EmitBranchable (ec, target, true);
3476: 					
3477: 				} else {
3478: 					Label tests_end = ig.DefineLabel ();
3479: 					left.EmitBranchable (ec, tests_end, true);
3480: 					right.EmitBranchable (ec, target, false);
3481: 					ig.MarkLabel (tests_end);
